@Prosa.Util.Minmax.leq_big_max : ∀ {X : Type u_1} [DecidableEq X] (F₁ F₂ : X → ℕ) (P : X → Bool) (xs : List X),
  (∀ x ∈ xs, P x = true → F₁ x ≤ F₂ x) →
    Prosa.Util.Minmax.bigMaxListCond xs P F₁ ≤ Prosa.Util.Minmax.bigMaxListCond xs P F₂

@Prosa.Util.Minmax.bigmax_witness_diff : ∀ {X : Type u_1} [DecidableEq X] {xs : List X} {P₁ P₂ : X → Bool} {F : X → ℕ},
  Prosa.Util.Minmax.bigMaxListCond xs P₁ F < Prosa.Util.Minmax.bigMaxListCond xs P₂ F →
    ∃ x ∈ xs, P₁ x = false ∧ P₂ x = true

@Prosa.Util.Minmax.bigmax_subset : ∀ {X : Type u_1} [DecidableEq X] {xs : List X} {P₁ P₂ : X → Bool} {F : X → ℕ},
  (∀ x ∈ xs, P₁ x = true → P₂ x = true) →
    Prosa.Util.Minmax.bigMaxListCond xs P₁ F ≤ Prosa.Util.Minmax.bigMaxListCond xs P₂ F
